// ParsePlain.vue as <conare-parse-plain>: parse, "Plain or Conare" (parse/Plain.vue): what a plain PDF reader gets beside what Conare read, the same page, one
// red handle between them, so the difference is seen and not claimed: a plain reader runs a table's columns together and
// finds nothing on a scan. The handle is a range input, so arrows move it too; each side keeps reading at any width. On
// a phone the two stack and there is no handle.
// Its rule for the read blocks' rows is parse-read's `tight`. `rootName` is the data-ds its root says.

/**
 * @summary A plain PDF reader's text beside Conare's, one handle between them.
 */
export class ParsePlain extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { answer: { type: Object }, rootName: { attribute: false }, at: { state: true } }

	answer?: ParseAnswer
	/** The root's data-ds. */
	rootName = 'parse-plain'
	private at = 50

	render() {
		const a = this.answer
		if (!a) return html``
		return html`<section data-ds="${this.rootName}" class="grid grid-cols-[minmax(0,4fr)_minmax(0,8fr)] items-stretch gap-6 max-lg:grid-cols-1" aria-label="a plain reader and Conare, the same page"><div class="m-1.25 self-start border border-edge bg-surface-subtle p-3 outline outline-offset-4 outline-edge">${staticHtml`<${tag('parse-sheet')} .parsed=${a.part} ?scan=${!!a.scan} plays mini></${tag('parse-sheet')}>`}</div><div class="ds-parseplain m-1.25" style=${`--at: ${this.at}%`}><div class="ds-parseplain-layer" data-side="plain"><p class="mb-3 type-meta text-fg-muted">A plain PDF reader</p>${!a.plain ? html`<p class="max-w-80 text-fg-soft">No text found. A scan is a picture, so a plain reader has nothing to read.</p>` : html`<pre class="m-0 font-code text-meta leading-4.5 break-words whitespace-pre-wrap text-fg-soft">${a.plain}</pre>`}</div><div class="ds-parseplain-layer" data-side="conare"><p class="mb-3 type-meta text-fg">Conare</p>${staticHtml`<${tag('parse-read')} .parsed=${a.part} tight></${tag('parse-read')}>`}</div><span class="ds-parseplain-rule" aria-hidden="true"><span>${icon(GripVertical, 'grip-vertical', { size: 12, strokeWidth: 1.5 })}</span></span><input .value=${String(this.at)} @input=${(e: Event) => { this.at = Number((e.target as HTMLInputElement).value) }} type="range" min="24" max="76" step="1" class="ds-parseplain-range" aria-label="move between a plain reader and Conare"></div></section>`
	}
}

define('parse-plain', ParsePlain)

/* ParsePlain.vue's <style>, as it is, but for its rule for the read blocks (parse-read's `tight`). */
.ds-parseplain { position: relative; display: grid; min-height: 560px; grid-template-columns: var(--at) minmax(0, 1fr); overflow: hidden; border: var(--ds-border-hairline) solid var(--ds-color-edge); outline: var(--ds-border-hairline) solid var(--ds-color-edge); outline-offset: 4px; }
.ds-parseplain:has(.ds-parseplain-range:focus-visible) { outline-color: var(--ds-color-edge-accent); }
.ds-parseplain-layer { min-width: 0; overflow: hidden; padding: 16px; background: var(--ds-color-surface); }
.ds-parseplain-layer[data-side="plain"] { background: var(--ds-color-surface-subtle); }
.ds-parseplain-rule { position: absolute; top: 0; bottom: 0; left: var(--at); width: 1px; background: var(--ds-color-edge-accent); pointer-events: none; }
.ds-parseplain-rule > span { position: absolute; top: 50%; left: 50%; display: flex; width: 20px; height: 32px; align-items: center; justify-content: center; background: var(--ds-color-home-red-press); color: var(--ds-color-fg-inverse); transform: translate(-50%, -50%); }
.ds-parseplain-range { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; cursor: ew-resize; opacity: 0; touch-action: pan-y; }
@media (max-width: 767px) {
  .ds-parseplain { min-height: 0; grid-template-columns: minmax(0, 1fr); }
  .ds-parseplain-rule, .ds-parseplain-range { display: none; }
  .ds-parseplain-layer[data-side="conare"] { border-top: var(--ds-border-hairline) solid var(--ds-color-edge-accent); }
}

import type { ReactiveController, ReactiveControllerHost } from 'lit'

/**
 * A document as Conare read it (POST /parse?layout=true): every region with its box (shares of the page), its reading
 * order and its OCR confidence. The parse views draw it; ParsePointController (useParsePoint) joins the page and the
 * text, so pointing at a region on one lights it on the other and a click pins it.
 */
export interface ParseBlock { type: string, bbox: [number, number, number, number], order: number, content: string, conf: number | null }
export interface ParsePart { page: number, markdown: string, ocr: boolean, confidence: number | null, blocks: ParseBlock[] }
export interface ParseAnswer {
	id: string
	name: string
	/** The page shown, and how many the file has. */
	page: number
	pages: number
	took_ms: number
	/** A scanned page (drawn as a scan). */
	scan?: boolean
	markdown: string
	/** What a plain PDF reader gets from the same page; empty for a scan. */
	plain: string
	part: ParsePart
}

/** A region's kind in plain words. */
export const REGION: Record<string, string> = { title: 'Title', text: 'Text', list: 'List', table: 'Table', image: 'Image', header: 'Header', footer: 'Footer', footnote: 'Footnote' }

/** A Markdown table's cells: its head, then its rows. */
export function tableOf(content: string) {
	const lines = content.split('\n').filter(l => l.trim().startsWith('|'))
	const cells = (l: string) => l.trim().replace(/^\||\|$/g, '').split('|').map(c => c.trim())
	return { head: lines[0] ? cells(lines[0]) : [], rows: lines.slice(2).map(cells) }
}

/** Totals read heavier on the page and in the text. */
export const isTotal = (label: string) => /^(total|net earnings)/i.test(label)

/** useParsePoint as a Lit controller: the region pointed at or pinned. */
export class ParsePointController implements ReactiveController {
	on: number | null = null
	pinned: number | null = null
	constructor(private host: ReactiveControllerHost) {
		host.addController(this)
	}
	hostConnected() {}
	get lit() {
		return this.on ?? this.pinned
	}
	point = (order: number | null) => {
		this.on = order
		this.host.requestUpdate()
	}
	pick = (order: number) => {
		this.pinned = this.pinned === order ? null : order
		this.host.requestUpdate()
	}
}
